import { useId } from 'react';
import type { ReactElement, ReactNode } from 'react';

import { Button } from '../Button/index.js';
import { Spinner } from '../Spinner/index.js';

export interface ChartFrameProps {
  title?: ReactNode;
  headingLevel?: 2 | 3 | 4 | 5;
  /** Where the numbers come from; shown as "Source: ...". */
  source?: string;
  loading?: boolean;
  /** Error text or node. Takes the place of the chart (unless `loading`). */
  error?: ReactNode;
  /** Shows a Retry button next to the error. */
  onRetry?: () => void;
  /** No data to plot. Shown instead of the chart. */
  empty?: boolean;
  /** Replaces the default empty message. */
  emptyState?: ReactNode;
  loadingLabel?: string;
  /** Minimum height of the chart area, so the page does not jump between states. */
  minHeight?: number | string;
  /** Text summary of the chart for screen readers; SVG charts are otherwise silent. */
  description?: string;
  /** The chart itself, for example an ApexCharts element. The package has no chart library. */
  children?: ReactNode;
  className?: string;
}

export function ChartFrame({
  title,
  headingLevel = 3,
  source,
  loading = false,
  error,
  onRetry,
  empty = false,
  emptyState,
  loadingLabel = 'Loading chart…',
  minHeight,
  description,
  children,
  className,
}: ChartFrameProps): ReactElement {
  const titleId = useId();
  const descriptionId = useId();
  const Heading = `h${headingLevel}` as 'h3';
  const classes = ['ss-chart-frame'];
  if (className) classes.push(className);

  const hasError = error !== undefined && error !== null && error !== false;

  let body: ReactNode;
  if (loading) {
    body = (
      <div className="ss-chart-state">
        <Spinner label={loadingLabel} />
      </div>
    );
  } else if (hasError) {
    body = (
      <div className="ss-chart-state" role="alert">
        <p className="ss-chart-message ss-chart-message-error">{error}</p>
        {onRetry && (
          <Button variant="outlined-primary" className="ss-chart-retry" onClick={onRetry}>
            Retry
          </Button>
        )}
      </div>
    );
  } else if (empty) {
    body = (
      <div className="ss-chart-state">
        {emptyState ?? <p className="ss-chart-message">No data to show yet.</p>}
      </div>
    );
  } else {
    body = children;
  }

  return (
    <section
      className={classes.join(' ')}
      aria-labelledby={title ? titleId : undefined}
      aria-describedby={description ? descriptionId : undefined}
      aria-busy={loading || undefined}
    >
      {title && (
        <Heading id={titleId} className="ss-chart-title">
          {title}
        </Heading>
      )}
      {description && (
        <p id={descriptionId} className="ss-visually-hidden">
          {description}
        </p>
      )}
      <div className="ss-chart-body" style={minHeight === undefined ? undefined : { minHeight }}>
        {body}
      </div>
      {source && <p className="ss-chart-source">Source: {source}</p>}
    </section>
  );
}
