import {
  createContext,
  useCallback,
  useContext,
  useId,
  useMemo,
  useState,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactElement,
  type ReactNode,
} from 'react';

export type TabsOrientation = 'horizontal' | 'vertical';

interface TabsContextValue {
  baseId: string;
  value: string;
  select: (value: string) => void;
  orientation: TabsOrientation;
  activation: 'automatic' | 'manual';
}

const TabsContext = createContext<TabsContextValue | null>(null);

function useTabs(part: string): TabsContextValue {
  const ctx = useContext(TabsContext);
  if (!ctx) throw new Error(`${part} must be rendered inside <Tabs>`);
  return ctx;
}

const slug = (value: string) => value.replace(/[^A-Za-z0-9_-]/g, '_');
const tabId = (base: string, value: string) => `${base}-tab-${slug(value)}`;
const panelId = (base: string, value: string) => `${base}-panel-${slug(value)}`;

export interface TabsProps {
  /** Controlled selected tab. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  orientation?: TabsOrientation;
  /** `automatic`: arrow keys select as they move focus. `manual`: Enter/Space selects. */
  activation?: 'automatic' | 'manual';
  className?: string;
  children: ReactNode;
}

export function Tabs({
  value,
  defaultValue = '',
  onValueChange,
  orientation = 'horizontal',
  activation = 'automatic',
  className,
  children,
}: TabsProps): ReactElement {
  const baseId = useId();
  const [inner, setInner] = useState(defaultValue);
  const current = value ?? inner;

  const select = useCallback(
    (next: string) => {
      if (value === undefined) setInner(next);
      onValueChange?.(next);
    },
    [value, onValueChange]
  );

  const ctx = useMemo(
    () => ({ baseId, value: current, select, orientation, activation }),
    [baseId, current, select, orientation, activation]
  );

  const classes = ['ss-tabs', `ss-tabs--${orientation}`];
  if (className) classes.push(className);
  return (
    <TabsContext.Provider value={ctx}>
      <div className={classes.join(' ')}>{children}</div>
    </TabsContext.Provider>
  );
}

export type TabListProps = HTMLAttributes<HTMLDivElement>;

/** Give it an `aria-label` or `aria-labelledby`. */
export function TabList({ className, onKeyDown, ...rest }: TabListProps): ReactElement {
  const { orientation, select, activation } = useTabs('TabList');

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;
    const tabs = Array.from(
      event.currentTarget.querySelectorAll<HTMLElement>('[role="tab"]:not([disabled])')
    );
    const index = tabs.indexOf(document.activeElement as HTMLElement);
    if (index === -1) return;

    const prev = orientation === 'horizontal' ? 'ArrowLeft' : 'ArrowUp';
    const next = orientation === 'horizontal' ? 'ArrowRight' : 'ArrowDown';
    let target: number | null = null;
    if (event.key === next) target = (index + 1) % tabs.length;
    else if (event.key === prev) target = (index - 1 + tabs.length) % tabs.length;
    else if (event.key === 'Home') target = 0;
    else if (event.key === 'End') target = tabs.length - 1;
    if (target === null) return;

    event.preventDefault();
    const el = tabs[target];
    el.focus();
    if (activation === 'automatic') select(el.dataset.value ?? '');
  };

  const classes = ['ss-tablist', `ss-tablist--${orientation}`];
  if (className) classes.push(className);
  return (
    <div
      role="tablist"
      aria-orientation={orientation}
      className={classes.join(' ')}
      onKeyDown={handleKeyDown}
      {...rest}
    />
  );
}

export interface TabProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'value'> {
  value: string;
}

export function Tab({ value, className, onClick, disabled, children, ...rest }: TabProps) {
  const ctx = useTabs('Tab');
  const selected = ctx.value === value;
  const classes = ['ss-tab'];
  if (selected) classes.push('ss-tab--selected');
  if (className) classes.push(className);
  return (
    <button
      type="button"
      role="tab"
      id={tabId(ctx.baseId, value)}
      data-value={value}
      aria-selected={selected}
      aria-controls={selected ? panelId(ctx.baseId, value) : undefined}
      tabIndex={selected ? 0 : -1}
      disabled={disabled}
      className={classes.join(' ')}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) ctx.select(value);
      }}
      {...rest}
    >
      {children}
    </button>
  );
}

export interface TabPanelProps extends HTMLAttributes<HTMLDivElement> {
  value: string;
}

/** Only the selected panel is mounted. */
export function TabPanel({ value, className, children, ...rest }: TabPanelProps) {
  const ctx = useTabs('TabPanel');
  if (ctx.value !== value) return null;
  const classes = ['ss-tabpanel'];
  if (className) classes.push(className);
  return (
    <div
      role="tabpanel"
      id={panelId(ctx.baseId, value)}
      aria-labelledby={tabId(ctx.baseId, value)}
      tabIndex={0}
      className={classes.join(' ')}
      {...rest}
    >
      {children}
    </div>
  );
}
