import type { ReactElement } from 'react';

import { cx } from '../../classes.js';

import { pageWindow } from './page-window.js';

export interface PaginationProps {
  /** 1-based. */
  currentPage: number;
  totalRecords: number;
  pageSize: number;
  onPageChange: (page: number) => void;
  /** Accessible name of the navigation landmark. */
  label?: string;
  className?: string;
}

function Chevron({ direction }: { direction: 'previous' | 'next' }): ReactElement {
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      className={`ss-pagination-icon ss-pagination-icon-${direction}`}
      viewBox="0 0 14 8"
      fill="none"
    >
      <path
        d="M13.6666 6.66667L6.99992 0L0.333252 6.66667L1.51659 7.85L6.99992 2.36667L12.4833 7.85L13.6666 6.66667Z"
        fill="currentColor"
      />
    </svg>
  );
}

export function Pagination({
  currentPage,
  totalRecords,
  pageSize,
  onPageChange,
  label = 'Pagination',
  className,
}: PaginationProps): ReactElement {
  const pageCount = Math.max(1, Math.ceil(totalRecords / pageSize));
  const classes = ['ss-pagination'];
  if (className) classes.push(className);

  const atFirst = currentPage <= 1;
  const atLast = currentPage >= pageCount;

  return (
    <nav aria-label={label} className={classes.join(' ')}>
      <button
        type="button"
        className="ss-pagination-item"
        aria-label="Previous page"
        disabled={atFirst}
        onClick={() => onPageChange(currentPage - 1)}
      >
        <Chevron direction="previous" />
      </button>
      {(totalRecords > 0 ? pageWindow(currentPage, pageCount) : []).map((page) => {
        const current = page === currentPage;
        return (
          <button
            key={page}
            type="button"
            className={cx('ss-pagination-item', current && 'ss-pagination-item-current')}
            aria-label={`Page ${page}`}
            aria-current={current ? 'page' : undefined}
            onClick={() => {
              if (!current) onPageChange(page);
            }}
          >
            {page}
          </button>
        );
      })}
      <button
        type="button"
        className="ss-pagination-item"
        aria-label="Next page"
        disabled={atLast}
        onClick={() => onPageChange(currentPage + 1)}
      >
        <Chevron direction="next" />
      </button>
    </nav>
  );
}
