/** Where an overlay mounts. Defaults to `document.body`; a plugin passes its own root. */
export type PortalContainer = HTMLElement | null | (() => HTMLElement | null);

export function resolveContainer(container?: PortalContainer): HTMLElement | null {
  if (typeof document === 'undefined') return null;
  const resolved = typeof container === 'function' ? container() : container;
  return resolved ?? document.body;
}

export const FOCUSABLE =
  'a[href], area[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), iframe, [tabindex]:not([tabindex="-1"]), [contenteditable="true"]';

export function focusableIn(root: HTMLElement): HTMLElement[] {
  return Array.from(root.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(
    (el) => !el.hasAttribute('hidden') && el.getAttribute('aria-hidden') !== 'true'
  );
}

/** Ref-counted, so nested modals lock once and the last one out restores the host's values. */
const locks = new WeakMap<HTMLElement, { count: number; overflow: string; paddingRight: string }>();

export function lockScroll(doc: Document): () => void {
  const body = doc.body;
  let entry = locks.get(body);
  if (!entry) {
    entry = { count: 0, overflow: body.style.overflow, paddingRight: body.style.paddingRight };
    const scrollbar = (doc.defaultView?.innerWidth ?? 0) - doc.documentElement.clientWidth;
    if (scrollbar > 0) {
      const current = parseFloat(doc.defaultView?.getComputedStyle(body).paddingRight ?? '0') || 0;
      body.style.paddingRight = `${current + scrollbar}px`;
    }
    body.style.overflow = 'hidden';
    locks.set(body, entry);
  }
  entry.count += 1;
  let released = false;
  return () => {
    if (released) return;
    released = true;
    const e = locks.get(body);
    if (!e) return;
    e.count -= 1;
    if (e.count === 0) {
      body.style.overflow = e.overflow;
      body.style.paddingRight = e.paddingRight;
      locks.delete(body);
    }
  };
}
