import { forwardRef } from 'react';
import type { ComponentType, InputHTMLAttributes, ReactNode, SVGProps } from 'react';

export type TabRadioVariant = 'primary' | 'secondary';

export interface TabRadioProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'size' | 'children' | 'checked'> {
  /** Controlled: the selected option of the group is the one that gets `checked`. */
  checked: boolean;
  /** Text on the tab. Defaults to `value`. */
  label?: ReactNode;
  /** `primary` has round ends, `secondary` rounded corners on a tinted track. */
  variant?: TabRadioVariant;
  /** An icon before the text. */
  Icon?: ComponentType<SVGProps<SVGSVGElement>>;
  /** Goes on the label, so a page can set the width. */
  className?: string;
}

/**
 * One option of a segmented control. A native radio, so arrow keys move between
 * the options of a `name` group and screen readers announce them as radios.
 */
export const TabRadio = forwardRef<HTMLInputElement, TabRadioProps>(function TabRadio(
  { label, variant = 'primary', Icon, className, value, checked, disabled, ...rest },
  ref
) {
  const classes = ['ss-radio-tab', `ss-radio-tab--${variant}`];
  if (checked) classes.push('ss-radio-tab--checked');
  if (disabled) classes.push('ss-radio-tab--disabled');
  if (className) classes.push(className);

  const faceClasses = ['ss-radio-tab-face', `ss-radio-tab-face--${variant}`];
  if (checked) faceClasses.push('ss-radio-tab-face--checked');

  return (
    <label className={classes.join(' ')}>
      <input
        ref={ref}
        type="radio"
        className={`ss-radio-tab-input ss-radio-tab-input--${variant}`}
        value={value}
        checked={checked}
        disabled={disabled}
        {...rest}
      />
      <span className={faceClasses.join(' ')}>
        {Icon && <Icon className="ss-radio-tab-icon" aria-hidden="true" />}
        {label ?? value}
      </span>
    </label>
  );
});
