import { forwardRef, useId } from 'react';
import type { ReactNode, TextareaHTMLAttributes } from 'react';

export interface TextareaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  label?: ReactNode;
  /** Help text under the field. */
  hint?: ReactNode;
  /** Error message. Turns the field red, sets `aria-invalid` and is announced. */
  error?: ReactNode;
  /** Goes on the wrapper, so a page can set the width or spacing. */
  className?: string;
}

export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(function Textarea(
  { label, hint, error, className, id, required, 'aria-describedby': describedBy, ...rest },
  ref
) {
  const generatedId = useId();
  const textareaId = id ?? generatedId;
  const hintId = `${textareaId}-hint`;
  const errorId = `${textareaId}-error`;
  const hasError = Boolean(error);

  const describedIds = [describedBy, hint ? hintId : undefined, hasError ? errorId : undefined]
    .filter(Boolean)
    .join(' ');

  return (
    <div className={className ? `ss-field ${className}` : 'ss-field'}>
      {label && (
        <label className="ss-field-label" htmlFor={textareaId}>
          {label}
          {required && (
            <span className="ss-field-required" aria-hidden="true">
              {' *'}
            </span>
          )}
        </label>
      )}
      <textarea
        ref={ref}
        id={textareaId}
        className={hasError ? 'ss-textarea ss-textarea--error' : 'ss-textarea'}
        required={required}
        aria-invalid={hasError || undefined}
        aria-describedby={describedIds || undefined}
        {...rest}
      />
      {hint && (
        <span id={hintId} className="ss-field-hint">
          {hint}
        </span>
      )}
      {hasError && (
        <span id={errorId} className="ss-field-error" role="alert">
          {error}
        </span>
      )}
    </div>
  );
});
