import {
  useEffect,
  useId,
  useRef,
  type KeyboardEvent,
  type MouseEvent,
  type ReactElement,
  type ReactNode,
  type RefObject,
} from 'react';
import { createPortal } from 'react-dom';

import { LayerContext, useLayer } from '../../internal/layers.js';
import {
  focusableIn,
  lockScroll,
  resolveContainer,
  type PortalContainer,
} from '../../internal/portal.js';

export interface ModalProps {
  open: boolean;
  /** Called on Escape and on a backdrop click. The parent decides whether to close. */
  onClose: () => void;
  /** Visible heading; the dialog is labelled by it. Without it pass `aria-label`. */
  title?: ReactNode;
  'aria-label'?: string;
  /** Use `alertdialog` for confirmations that need an answer. */
  role?: 'dialog' | 'alertdialog';
  /** Where to mount. Default `document.body`. */
  container?: PortalContainer;
  /** Element to focus on open. Default: the first focusable element, else the dialog. */
  initialFocusRef?: RefObject<HTMLElement>;
  closeOnBackdropClick?: boolean;
  /** Bottom row for actions, e.g. buttons. */
  footer?: ReactNode;
  className?: string;
  children?: ReactNode;
}

export function Modal({
  open,
  onClose,
  title,
  'aria-label': ariaLabel,
  role = 'dialog',
  container,
  initialFocusRef,
  closeOnBackdropClick = true,
  footer,
  className,
  children,
}: ModalProps): ReactElement | null {
  const titleId = useId();
  const dialogRef = useRef<HTMLDivElement>(null);
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  const initialFocusRefRef = useRef(initialFocusRef);
  initialFocusRefRef.current = initialFocusRef;
  const mountNode = open ? resolveContainer(container) : null;
  const handle = useLayer(!!mountNode, dialogRef);

  useEffect(() => {
    if (!mountNode) return;
    const dialog = dialogRef.current;
    if (!dialog) return;
    const doc = dialog.ownerDocument;
    const opener = doc.activeElement instanceof HTMLElement ? doc.activeElement : null;
    const unlock = lockScroll(doc);

    const target = initialFocusRefRef.current?.current ?? focusableIn(dialog)[0] ?? dialog;
    target.focus();

    // The host admin may move focus (its own scripts, a notice). Pull it back.
    const keepFocus = (event: FocusEvent) => {
      // Only the topmost layer traps; focus inside a popover or modal opened from here is fine.
      if (!handle.isTop()) return;
      if (event.target instanceof Node && !handle.owns(event.target)) {
        (focusableIn(dialog)[0] ?? dialog).focus();
      }
    };
    doc.addEventListener('focusin', keepFocus);

    return () => {
      doc.removeEventListener('focusin', keepFocus);
      unlock();
      if (opener && opener.isConnected) opener.focus({ preventScroll: true });
    };
  }, [mountNode, handle]);

  if (!mountNode) return null;

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    // Keys bubble here from overlays opened inside; the one on top handles them.
    if (!handle.isTop()) return;
    if (event.key === 'Escape') {
      event.stopPropagation();
      event.preventDefault();
      onCloseRef.current();
      return;
    }
    if (event.key !== 'Tab') return;
    const dialog = dialogRef.current;
    if (!dialog) return;
    const items = focusableIn(dialog);
    if (items.length === 0) {
      event.preventDefault();
      dialog.focus();
      return;
    }
    const first = items[0];
    const last = items[items.length - 1];
    const active = dialog.ownerDocument.activeElement;
    if (event.shiftKey && (active === first || active === dialog)) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && active === last) {
      event.preventDefault();
      first.focus();
    }
  };

  const handleBackdropClick = (event: MouseEvent<HTMLDivElement>) => {
    if (handle.isTop() && closeOnBackdropClick && event.target === event.currentTarget)
      onCloseRef.current();
  };

  const classes = ['ss-modal'];
  if (className) classes.push(className);

  return createPortal(
    // The backdrop only forwards pointer clicks; keyboard users close with Escape.
    <LayerContext.Provider value={handle.layer}>
      <div className="ss-modal-backdrop" onMouseDown={handleBackdropClick}>
        <div
          ref={dialogRef}
          role={role}
          aria-modal="true"
          aria-labelledby={title ? titleId : undefined}
          aria-label={title ? undefined : ariaLabel}
          tabIndex={-1}
          className={classes.join(' ')}
          onKeyDown={handleKeyDown}
        >
          {title ? (
            <h2 id={titleId} className="ss-modal-title">
              {title}
            </h2>
          ) : null}
          <div className="ss-modal-body">{children}</div>
          {footer ? <div className="ss-modal-footer">{footer}</div> : null}
        </div>
      </div>
    </LayerContext.Provider>,
    mountNode
  );
}
