import type { ButtonHTMLAttributes, ReactElement } from 'react';

/**
 * `contained-inverse` is the dark button. `link` is an underlined text button that
 * sizes to its text; the caller sets its colour and size with classes.
 */
export type ButtonVariant = 'contained-primary' | 'outlined-primary' | 'contained-inverse' | 'link';

/** Like a native button, `type` is left to the browser (submit inside a form). */
export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
}

export function Button({
  variant,
  className,
  disabled,
  children,
  ...rest
}: ButtonProps): ReactElement {
  const classes = ['ss-button'];
  if (disabled && variant === 'link') classes.push('ss-button--link', 'ss-button--link-disabled');
  else if (disabled) classes.push('ss-button--disabled');
  else if (variant) classes.push(`ss-button--${variant}`);
  if (className) classes.push(className);

  return (
    <button className={classes.join(' ')} disabled={disabled} {...rest}>
      {children}
    </button>
  );
}
