import { useMemo, useState } from 'react';
import type { Key, ReactElement, ReactNode } from 'react';

import { cx } from '../../classes.js';
import { Pagination } from '../Pagination/index.js';

export type SortDirection = 'asc' | 'desc';

export interface SortState {
  key: string;
  direction: SortDirection;
}

export interface TableColumn<Row> {
  /** Unique id; also the default property read from the row. */
  key: string;
  header: ReactNode;
  /** Cell value for the default render, sort and filter. Defaults to `row[key]`. */
  value?: (row: Row) => unknown;
  /** Replaces the default cell content. */
  render?: (row: Row, rowIndex: number) => ReactNode;
  sortable?: boolean;
  /** Replaces the default comparison (numbers numerically, text by locale). */
  compare?: (a: Row, b: Row) => number;
  /** Replaces the default filter (case-insensitive "contains" on the cell value). */
  filter?: (row: Row, filterValue: string) => boolean;
  align?: 'start' | 'center' | 'end';
}

export type TableStripes = 'surface-first' | 'subtle-first' | 'none';

export interface TableProps<Row> {
  columns: TableColumn<Row>[];
  rows: Row[];
  /** Stable key per row. Defaults to the row index. */
  getRowKey?: (row: Row, index: number) => Key;
  /** Names the table for screen readers (rendered as a visually hidden caption). */
  caption: string;

  /** Controlled sort. `null` means unsorted. Leave out for an uncontrolled table. */
  sort?: SortState | null;
  defaultSort?: SortState | null;
  /** Gets the next state and the clicked column key. Clicking cycles asc, desc, unsorted. */
  onSortChange?: (next: SortState | null, columnKey: string) => void;
  /** Rows arrive already sorted (server side): the header still shows and reports the sort. */
  manualSort?: boolean;

  /** Column key to filter text. Filtering is local to the rows given. */
  filters?: Record<string, string>;

  /** Rows with the same group value are shown together under a heading row. */
  groupBy?: (row: Row) => string;
  renderGroupHeader?: (group: string, rows: Row[]) => ReactNode;

  /** Pagination shows when `pageSize` is set, even for 0 rows. 1-based. */
  pageSize?: number;
  page?: number;
  defaultPage?: number;
  onPageChange?: (page: number) => void;
  /** Set when the rows are one server-side page: no local slicing, this is the full count. */
  totalRecords?: number;

  /** Shown instead of the rows when there are none. */
  empty?: ReactNode;
  fixed?: boolean;
  stripes?: TableStripes;
  className?: string;
}

function cellValue<Row>(column: TableColumn<Row>, row: Row): unknown {
  return column.value ? column.value(row) : (row as Record<string, unknown>)[column.key];
}

function isBlank(value: unknown): boolean {
  return value === null || value === undefined || value === '';
}

function defaultCompare(a: unknown, b: unknown): number {
  if (typeof a === 'number' && typeof b === 'number') return a - b;
  return String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: 'base' });
}

function sortRows<Row>(rows: Row[], column: TableColumn<Row>, direction: SortDirection): Row[] {
  const factor = direction === 'asc' ? 1 : -1;
  return rows
    .map((row, index) => ({ row, index }))
    .sort((x, y) => {
      if (column.compare) return factor * column.compare(x.row, y.row) || x.index - y.index;
      const a = cellValue(column, x.row);
      const b = cellValue(column, y.row);
      // Blank values go last in both directions.
      if (isBlank(a) || isBlank(b))
        return Number(isBlank(a)) - Number(isBlank(b)) || x.index - y.index;
      return factor * defaultCompare(a, b) || x.index - y.index;
    })
    .map(({ row }) => row);
}

function matchesFilter<Row>(column: TableColumn<Row>, row: Row, text: string): boolean {
  if (column.filter) return column.filter(row, text);
  const value = cellValue(column, row);
  return String(value ?? '')
    .toLowerCase()
    .includes(text.toLowerCase());
}

function nextSort(current: SortState | null, key: string): SortState | null {
  if (!current || current.key !== key) return { key, direction: 'asc' };
  return current.direction === 'asc' ? { key, direction: 'desc' } : null;
}

const ARIA_SORT = { asc: 'ascending', desc: 'descending' } as const;

function SortIcons({ direction }: { direction: SortDirection | null }): ReactElement {
  const icon = (kind: 'up' | 'down') => (
    <svg
      aria-hidden="true"
      focusable="false"
      viewBox="0 0 8.3333197 4.1666999"
      className={cx(
        'ss-table-sort-icon',
        `ss-table-sort-icon-${kind}`,
        direction === (kind === 'up' ? 'asc' : 'desc') && 'ss-table-sort-icon-active'
      )}
    >
      <path d="M 0,0 4.16672,4.1667 8.33332,0 Z" fill="currentColor" />
    </svg>
  );
  return (
    <span className="ss-table-sort-icons">
      {icon('up')}
      {icon('down')}
    </span>
  );
}

/**
 * Headless-style table: describe `columns`, pass `rows`, and the table sorts, filters,
 * groups and paginates them. Every column can replace its cell with `render`.
 */
export function Table<Row>({
  columns,
  rows,
  getRowKey,
  caption,
  sort,
  defaultSort = null,
  onSortChange,
  manualSort = false,
  filters,
  groupBy,
  renderGroupHeader,
  pageSize,
  page,
  defaultPage = 1,
  onPageChange,
  totalRecords,
  empty,
  fixed = false,
  stripes = 'surface-first',
  className,
}: TableProps<Row>): ReactElement {
  const [innerSort, setInnerSort] = useState<SortState | null>(defaultSort);
  const [innerPage, setInnerPage] = useState(defaultPage);

  const activeSort = sort === undefined ? innerSort : sort;
  const serverPaged = totalRecords !== undefined;

  const processed = useMemo(() => {
    let result = rows;
    if (filters) {
      const active = columns.filter((c) => !isBlank(filters[c.key]));
      if (active.length > 0) {
        result = result.filter((row) => active.every((c) => matchesFilter(c, row, filters[c.key])));
      }
    }
    if (activeSort && !manualSort) {
      const column = columns.find((c) => c.key === activeSort.key);
      if (column) result = sortRows(result, column, activeSort.direction);
    }
    return result;
  }, [rows, columns, filters, activeSort, manualSort]);

  const total = serverPaged ? totalRecords : processed.length;
  const pageCount = pageSize ? Math.max(1, Math.ceil(total / pageSize)) : 1;
  const currentPage = Math.min(Math.max(1, page ?? innerPage), pageCount);

  const visible = useMemo(() => {
    if (!pageSize || serverPaged) return processed;
    return processed.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  }, [processed, pageSize, serverPaged, currentPage]);

  const groups = useMemo(() => {
    if (!groupBy) return [{ name: null as string | null, rows: visible, start: 0 }];
    const order: string[] = [];
    const byName = new Map<string, Row[]>();
    visible.forEach((row) => {
      const name = groupBy(row);
      if (!byName.has(name)) {
        byName.set(name, []);
        order.push(name);
      }
      byName.get(name)?.push(row);
    });
    let start = 0;
    return order.map((name) => {
      const groupRows = byName.get(name) ?? [];
      const group = { name, rows: groupRows, start };
      start += groupRows.length;
      return group;
    });
  }, [groupBy, visible]);

  const handleSort = (column: TableColumn<Row>) => {
    const next = nextSort(activeSort, column.key);
    if (sort === undefined) setInnerSort(next);
    onSortChange?.(next, column.key);
  };

  const handlePageChange = (next: number) => {
    if (page === undefined) setInnerPage(next);
    onPageChange?.(next);
  };

  const classes = ['ss-table'];
  classes.push(fixed ? 'ss-table-fixed' : 'ss-table-auto');
  if (className) classes.push(className);

  const rowClass = (index: number) => {
    if (stripes === 'none') return 'ss-table-row';
    const odd = index % 2 === 0; // 1st, 3rd, ... visible row
    const plain = stripes === 'surface-first' ? odd : !odd;
    return `ss-table-row ${plain ? 'ss-table-row-surface' : 'ss-table-row-subtle'}`;
  };

  return (
    <div className="ss-table-wrap">
      <table className={classes.join(' ')}>
        <caption className="ss-visually-hidden">{caption}</caption>
        <thead>
          <tr>
            {columns.map((column) => {
              const direction = activeSort?.key === column.key ? activeSort.direction : null;
              return (
                <th
                  key={column.key}
                  scope="col"
                  className="ss-table-th"
                  aria-sort={
                    column.sortable ? (direction ? ARIA_SORT[direction] : 'none') : undefined
                  }
                >
                  {column.sortable ? (
                    <button
                      type="button"
                      className="ss-table-sort"
                      onClick={() => handleSort(column)}
                    >
                      <span className="ss-table-th-label">{column.header}</span>
                      <SortIcons direction={direction} />
                    </button>
                  ) : (
                    <div className="ss-table-th-content">
                      <span className="ss-table-th-label">{column.header}</span>
                    </div>
                  )}
                </th>
              );
            })}
          </tr>
        </thead>
        {visible.length === 0 ? (
          <tbody>
            {empty !== undefined && (
              <tr>
                <td colSpan={columns.length} className="ss-table-empty">
                  {empty}
                </td>
              </tr>
            )}
          </tbody>
        ) : (
          groups.map((group) => (
            <tbody key={group.name ?? '__all'}>
              {group.name !== null && (
                <tr className="ss-table-group-row">
                  <th scope="rowgroup" colSpan={columns.length} className="ss-table-group">
                    {renderGroupHeader ? renderGroupHeader(group.name, group.rows) : group.name}
                  </th>
                </tr>
              )}
              {group.rows.map((row, i) => {
                const index = group.start + i;
                return (
                  <tr key={getRowKey ? getRowKey(row, index) : index} className={rowClass(index)}>
                    {columns.map((column) => (
                      <td
                        key={column.key}
                        className={cx(
                          'ss-table-td',
                          column.align && column.align !== 'center' && `ss-table-td-${column.align}`
                        )}
                      >
                        {column.render
                          ? column.render(row, index)
                          : String(cellValue(column, row) ?? '')}
                      </td>
                    ))}
                  </tr>
                );
              })}
            </tbody>
          ))
        )}
      </table>
      {pageSize !== undefined && (
        <Pagination
          currentPage={currentPage}
          totalRecords={total}
          pageSize={pageSize}
          onPageChange={handlePageChange}
        />
      )}
    </div>
  );
}
