const WINDOW = 3;

/** Up to three page numbers around the current one, kept inside 1..pageCount. */
export function pageWindow(currentPage: number, pageCount: number): number[] {
  const size = Math.min(WINDOW, pageCount);
  const start = Math.max(1, Math.min(currentPage - 1, pageCount - size + 1));
  return Array.from({ length: size }, (_, i) => start + i);
}
