import { cloneElement, isValidElement, useId, useState } from 'react';
import type { KeyboardEvent, ReactElement, ReactNode } from 'react';

export interface TooltipProps {
  /** The trigger. Give it something focusable (a button, a link) so keyboard users reach it. */
  children: ReactNode;
  content: ReactNode;
  /** Goes on the wrapper. */
  className?: string;
}

/**
 * Shows on hover and on focus, hides on leave, blur or Escape (WCAG 1.4.13). The bubble
 * sits inside the wrapper, so the pointer can move onto it without it closing.
 * The trigger gets `aria-describedby` pointing at the bubble.
 */
export function Tooltip({ children, content, className }: TooltipProps) {
  const id = useId();
  const [open, setOpen] = useState(false);

  const onKeyDown = (event: KeyboardEvent<HTMLSpanElement>) => {
    if (event.key === 'Escape' && open) {
      setOpen(false);
      event.stopPropagation();
    }
  };

  const trigger = isValidElement<{ 'aria-describedby'?: string }>(children) ? (
    cloneElement(children as ReactElement<{ 'aria-describedby'?: string }>, {
      'aria-describedby': [children.props['aria-describedby'], id].filter(Boolean).join(' '),
    })
  ) : (
    // Plain text has nothing to focus, so the wrapper becomes the stop.
    <span tabIndex={0} aria-describedby={id}>
      {children}
    </span>
  );

  return (
    <span
      className={className ? `ss-tooltip ${className}` : 'ss-tooltip'}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
      onFocus={() => setOpen(true)}
      onBlur={() => setOpen(false)}
      onKeyDown={onKeyDown}
    >
      {trigger}
      <span
        id={id}
        role="tooltip"
        className={open ? 'ss-tooltip-bubble ss-tooltip-bubble--open' : 'ss-tooltip-bubble'}
        hidden={!open}
      >
        {content}
      </span>
    </span>
  );
}
