import { useId, useState } from 'react';
import type { ElementType, ReactElement, ReactNode } from 'react';

export interface AccordionProps {
  title: ReactNode;
  /** Level of the title heading. Pick the one that fits the page outline. */
  headingLevel?: 2 | 3 | 4 | 5;
  /** The text. A few lines show while it is collapsed. */
  children: ReactNode;
  collapsedLabel?: string;
  expandedLabel?: string;
  defaultExpanded?: boolean;
  className?: string;
}

/** A title and a short text; the toggle button reveals the rest of the text. */
export function Accordion({
  title,
  headingLevel = 2,
  children,
  collapsedLabel = 'Read more',
  expandedLabel = 'Read less',
  defaultExpanded = false,
  className,
}: AccordionProps): ReactElement {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const bodyId = useId();
  const Heading = `h${headingLevel}` as ElementType;
  const classes = ['ss-accordion'];
  if (className) classes.push(className);

  return (
    <div className={classes.join(' ')}>
      <Heading className="ss-accordion-title">{title}</Heading>
      <div
        id={bodyId}
        className={expanded ? 'ss-accordion-body ss-accordion-body--expanded' : 'ss-accordion-body'}
      >
        <p className="ss-accordion-text">{children}</p>
      </div>
      <button
        type="button"
        className="ss-accordion-toggle"
        aria-expanded={expanded}
        aria-controls={bodyId}
        onClick={() => setExpanded(!expanded)}
      >
        <span className="ss-accordion-icon" aria-hidden="true">
          <svg viewBox="0 0 8 8" width="12" height="12" focusable="false">
            <path
              d="M0 4h8M4 0v8"
              stroke="currentColor"
              strokeWidth="1.33"
              strokeLinecap="butt"
              fill="none"
            />
          </svg>
        </span>
        {expanded ? expandedLabel : collapsedLabel}
      </button>
    </div>
  );
}
