import { createContext, forwardRef, useContext, useId } from 'react';
import type { FieldsetHTMLAttributes, InputHTMLAttributes, ReactNode } from 'react';

interface RadioGroupContextValue {
  name: string;
  value?: string;
  onValueChange?: (value: string) => void;
  disabled?: boolean;
}

const RadioGroupContext = createContext<RadioGroupContextValue | null>(null);

export interface RadioGroupProps
  extends Omit<FieldsetHTMLAttributes<HTMLFieldSetElement>, 'onChange' | 'children'> {
  /** The group's name. Defaults to a generated one. */
  name?: string;
  legend?: ReactNode;
  /** Controlled selected value. */
  value?: string;
  onValueChange?: (value: string) => void;
  children: ReactNode;
}

/** A fieldset of radios that share a name, so arrow keys move between them natively. */
export function RadioGroup({
  name,
  legend,
  value,
  onValueChange,
  disabled,
  className,
  children,
  ...rest
}: RadioGroupProps) {
  const generatedName = useId();
  const classes = className ? `ss-radio-group ${className}` : 'ss-radio-group';

  return (
    <RadioGroupContext.Provider
      value={{ name: name ?? generatedName, value, onValueChange, disabled }}
    >
      <fieldset className={classes} disabled={disabled} {...rest}>
        {legend && <legend className="ss-radio-legend">{legend}</legend>}
        {children}
      </fieldset>
    </RadioGroupContext.Provider>
  );
}

export interface RadioProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'size' | 'children'> {
  /** Text next to the circle. Without it, give the input an `aria-label`. */
  label?: ReactNode;
  /** Goes on the label row, so a page can set spacing. */
  className?: string;
}

/** A native radio. Inside a `RadioGroup` it takes the group's name and selection. */
export const Radio = forwardRef<HTMLInputElement, RadioProps>(function Radio(
  { label, className, disabled, value, checked, onChange, name, ...rest },
  ref
) {
  const group = useContext(RadioGroupContext);
  const isDisabled = disabled ?? group?.disabled;
  const rowClasses = ['ss-radio-row'];
  if (isDisabled) rowClasses.push('ss-radio-row--disabled');
  if (className) rowClasses.push(className);

  const grouped = group !== null && typeof value === 'string';
  return (
    <label className={rowClasses.join(' ')}>
      <input
        ref={ref}
        type="radio"
        className="ss-radio"
        name={name ?? group?.name}
        value={value}
        checked={
          checked ?? (grouped && group.value !== undefined ? group.value === value : undefined)
        }
        onChange={(event) => {
          onChange?.(event);
          if (grouped) group.onValueChange?.(value);
        }}
        disabled={isDisabled}
        {...rest}
      />
      {label && <span className="ss-radio-text">{label}</span>}
    </label>
  );
});
