import {
  useEffect,
  useLayoutEffect,
  useRef,
  type KeyboardEvent,
  type ReactElement,
  type ReactNode,
  type RefObject,
} from 'react';
import { createPortal } from 'react-dom';

import { LayerContext, useLayer } from '../../internal/layers.js';
import { focusableIn, resolveContainer, type PortalContainer } from '../../internal/portal.js';

export type PopoverPlacement = 'bottom-start' | 'bottom-end' | 'top-start' | 'top-end';

export interface PopoverProps {
  open: boolean;
  /** Called on Escape and on a press outside the popover and its anchor. */
  onClose: () => void;
  /** The element the popover is placed against. */
  anchorRef: RefObject<HTMLElement>;
  placement?: PopoverPlacement;
  /** Gap in px between anchor and popover. May be negative to overlap. */
  offset?: number;
  matchAnchorWidth?: boolean;
  /** Where to mount. Default `document.body`. The popover is `position: fixed`. */
  container?: PortalContainer;
  /** `dialog` needs a label. Menus pass `none` and put their own role inside. */
  role?: string;
  'aria-label'?: string;
  'aria-labelledby'?: string;
  id?: string;
  /** Move focus into the popover on open (first focusable, else the popover). */
  autoFocus?: boolean;
  /** On close, give focus back to whatever had it before opening. */
  returnFocus?: boolean;
  className?: string;
  children?: ReactNode;
}

const useIsoLayoutEffect = typeof document === 'undefined' ? useEffect : useLayoutEffect;

export function Popover({
  open,
  onClose,
  anchorRef,
  placement = 'bottom-start',
  offset = 4,
  matchAnchorWidth = false,
  container,
  role = 'dialog',
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledBy,
  id,
  autoFocus = true,
  returnFocus = true,
  className,
  children,
}: PopoverProps): ReactElement | null {
  const ref = useRef<HTMLDivElement>(null);
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  // Set when the popover closes because its anchor scrolled away: focusing the
  // anchor then would drag the page back to it.
  const skipReturn = useRef(false);
  const mountNode = open ? resolveContainer(container) : null;
  const handle = useLayer(!!mountNode, ref);

  // Written straight to the element (no state), so the popover is already in place
  // when children focus themselves in their own effects.
  useIsoLayoutEffect(() => {
    const el = ref.current;
    const anchor = anchorRef.current;
    if (!mountNode || !el || !anchor) return;
    const win = el.ownerDocument.defaultView ?? window;
    const place = () => {
      const a = anchor.getBoundingClientRect();
      if (matchAnchorWidth) el.style.width = `${a.width}px`;
      const width = el.offsetWidth;
      const height = el.offsetHeight;
      const left = placement.endsWith('end') ? a.right - width : a.left;
      const top = placement.startsWith('top') ? a.top - height - offset : a.bottom + offset;
      el.style.left = `${Math.max(0, Math.min(left, win.innerWidth - width))}px`;
      el.style.top = `${Math.max(0, top)}px`;
    };
    // Follow the anchor while the page or an ancestor scrolls; once it has left the
    // viewport there is nothing to point at, so close.
    const follow = (event: Event) => {
      if (event.target instanceof Node && el.contains(event.target)) return;
      const a = anchor.getBoundingClientRect();
      if (a.bottom < 0 || a.top > win.innerHeight || a.right < 0 || a.left > win.innerWidth) {
        skipReturn.current = true;
        onCloseRef.current();
        return;
      }
      place();
    };
    place();
    win.addEventListener('resize', follow);
    win.addEventListener('scroll', follow, true);
    return () => {
      win.removeEventListener('resize', follow);
      win.removeEventListener('scroll', follow, true);
    };
  }, [mountNode, anchorRef, placement, offset, matchAnchorWidth]);

  useEffect(() => {
    const el = ref.current;
    if (!mountNode || !el) return;
    const anchor = anchorRef.current;
    const doc = el.ownerDocument;
    const opener =
      doc.activeElement instanceof HTMLElement && doc.activeElement !== doc.body
        ? doc.activeElement
        : null;

    skipReturn.current = false;
    if (autoFocus) (focusableIn(el)[0] ?? el).focus({ preventScroll: true });

    const outside = (event: Event) => {
      const target = event.target as Node | null;
      if (!target || handle.owns(target) || anchor?.contains(target)) return;
      onCloseRef.current();
    };
    // Escape while focus is still on the anchor (popover opened without taking focus).
    const escape = (event: globalThis.KeyboardEvent) => {
      if (event.key === 'Escape' && !event.defaultPrevented && handle.isTop()) onCloseRef.current();
    };
    doc.addEventListener('mousedown', outside);
    doc.addEventListener('touchstart', outside);
    doc.addEventListener('keydown', escape);

    return () => {
      doc.removeEventListener('mousedown', outside);
      doc.removeEventListener('touchstart', outside);
      doc.removeEventListener('keydown', escape);
      // Focus that sat inside the popover is now on <body>; hand it back. If the
      // user moved on to another control, leave it there.
      const active = doc.activeElement;
      if (returnFocus && !skipReturn.current && (!active || active === doc.body)) {
        const target = opener && opener.isConnected ? opener : anchor;
        target?.focus({ preventScroll: true });
      }
    };
  }, [mountNode, anchorRef, autoFocus, returnFocus, handle]);

  if (!mountNode) return null;

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === 'Escape' && handle.isTop()) {
      // Stops a surrounding Modal from also closing.
      event.stopPropagation();
      event.preventDefault();
      onCloseRef.current();
      return;
    }
    if (event.key !== 'Tab' || event.defaultPrevented) return;
    // Not modal: Tab past either end leaves the popover. Close it and continue from the
    // anchor inside whatever layer opened it, so a surrounding Modal's trap keeps holding.
    const el = ref.current;
    const anchor = anchorRef.current;
    if (!el || !anchor) return;
    const items = focusableIn(el);
    const active = el.ownerDocument.activeElement;
    const atEnd = event.shiftKey
      ? active === el || active === items[0]
      : active === el || active === items[items.length - 1];
    if (!atEnd) return;
    event.preventDefault();
    const scope = handle.layer.parent?.getElement() ?? el.ownerDocument.body;
    const order = focusableIn(scope).filter((n) => !el.contains(n));
    const at = order.indexOf(anchor);
    const target = event.shiftKey
      ? anchor
      : order[at + 1] ?? (handle.layer.parent ? order[0] : undefined) ?? anchor;
    onCloseRef.current();
    target.focus({ preventScroll: true });
  };

  const classes = ['ss-popover'];
  if (className) classes.push(className);
  return createPortal(
    <LayerContext.Provider value={handle.layer}>
      <div
        ref={ref}
        id={id}
        role={role}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledBy}
        tabIndex={-1}
        className={classes.join(' ')}
        onKeyDown={handleKeyDown}
      >
        {children}
      </div>
    </LayerContext.Provider>,
    mountNode
  );
}
