import type { ElementType, ReactElement, ReactNode } from 'react';

export interface EmptyStateProps {
  title: ReactNode;
  description?: ReactNode;
  /** Decorative icon or illustration; hidden from screen readers. */
  icon?: ReactNode;
  /** Next step, for example a Button. */
  action?: ReactNode;
  headingLevel?: 2 | 3 | 4 | 5;
  className?: string;
}

export function EmptyState({
  title,
  description,
  icon,
  action,
  headingLevel = 3,
  className,
}: EmptyStateProps): ReactElement {
  const Heading = `h${headingLevel}` as ElementType;
  const classes = ['ss-empty'];
  if (className) classes.push(className);

  return (
    <div className={classes.join(' ')}>
      {icon && (
        <div className="ss-empty-icon" aria-hidden="true">
          {icon}
        </div>
      )}
      <Heading className="ss-empty-title">{title}</Heading>
      {description && <p className="ss-empty-description">{description}</p>}
      {action && <div className="ss-empty-action">{action}</div>}
    </div>
  );
}
