import { forwardRef, useId } from 'react';
import type { InputHTMLAttributes, ReactNode } from 'react';

export type InputSize = 'sm' | 'md';

export interface InputProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'size'> {
  label?: ReactNode;
  /** Help text under the field. */
  hint?: ReactNode;
  /** Error message. Turns the field red, sets `aria-invalid` and is announced. */
  error?: ReactNode;
  /** An icon at the right end of the field, for example a magnifier. Decoration: it ignores the pointer. */
  endAdornment?: ReactNode;
  /** `sm` is 40px high, `md` (default) 48px. */
  size?: InputSize;
  /** Goes on the wrapper, so a page can set the width. */
  className?: string;
}

export const Input = forwardRef<HTMLInputElement, InputProps>(function Input(
  {
    label,
    hint,
    error,
    size = 'md',
    endAdornment,
    className,
    id,
    required,
    'aria-describedby': describedBy,
    ...rest
  },
  ref
) {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const hintId = `${inputId}-hint`;
  const errorId = `${inputId}-error`;
  const hasError = Boolean(error);

  const describedIds = [describedBy, hint ? hintId : undefined, hasError ? errorId : undefined]
    .filter(Boolean)
    .join(' ');

  const inputClasses = ['ss-input'];
  if (size === 'sm') inputClasses.push('ss-input--sm');
  if (hasError) inputClasses.push('ss-input--error');

  const inputElement = (
    <input
      ref={ref}
      id={inputId}
      className={inputClasses.join(' ')}
      required={required}
      aria-invalid={hasError || undefined}
      aria-describedby={describedIds || undefined}
      {...rest}
    />
  );

  return (
    <div className={className ? `ss-field ${className}` : 'ss-field'}>
      {label && (
        <label className="ss-field-label" htmlFor={inputId}>
          {label}
          {required && (
            <span className="ss-field-required" aria-hidden="true">
              {' *'}
            </span>
          )}
        </label>
      )}
      {endAdornment ? (
        <div className="ss-input-wrap">
          {inputElement}
          <span className="ss-input-adornment" aria-hidden="true">
            {endAdornment}
          </span>
        </div>
      ) : (
        inputElement
      )}
      {hint && (
        <span id={hintId} className="ss-field-hint">
          {hint}
        </span>
      )}
      {hasError && (
        <span id={errorId} className="ss-field-error" role="alert">
          {error}
        </span>
      )}
    </div>
  );
});
