import { useId, useRef, useState } from 'react';
import type { ChangeEvent, DragEvent, ReactElement, ReactNode, SVGProps } from 'react';

import { ColoredIcon } from '../ColoredIcon/index.js';

export interface FileDropzoneProps {
  /** What to do, for example "Drag and drop a CSV file with users data". */
  description: ReactNode;
  /** The chosen file, shown under the drop area; `null` for none. */
  file: File | null;
  /** The file that was dropped or picked. When several are dropped, the first one. */
  onFileSelect: (file: File) => void;
  /** The remove button next to the file name was pressed. */
  onRemove: () => void;
  /** Passed to the file input, for example `.csv`. */
  accept?: string;
  /** Why the file cannot be used. Turns the file row red and is announced. */
  error?: ReactNode;
  /** A problem that does not stop the upload. Shown under the file row. */
  warning?: ReactNode;
  /** `tall` makes the drop area 20rem high (the Explore upload form); `default` fits its content. */
  size?: 'default' | 'tall';
  /** Text of the link that opens the file dialog. */
  browseLabel?: string;
  /** Accessible name of the remove button. */
  removeLabel?: string;
  id?: string;
  className?: string;
}

function UploadGlyph(props: SVGProps<SVGSVGElement>) {
  return (
    <svg viewBox="0 0 20 20" {...props}>
      <path
        d="M8.75 15V4.8125L5.5 8.0625L3.75 6.25L10 0L16.25 6.25L14.5 8.0625L11.25 4.8125V15H8.75ZM2.5 20C1.8125 20 1.22396 19.7552 0.734375 19.2656C0.244792 18.776 0 18.1875 0 17.5V13.75H2.5V17.5H17.5V13.75H20V17.5C20 18.1875 19.7552 18.776 19.2656 19.2656C18.776 19.7552 18.1875 20 17.5 20H2.5Z"
        fill="currentColor"
      />
    </svg>
  );
}

const SELECT_FIRST = (files: FileList | null | undefined): File | undefined => files?.[0];

/**
 * A drop area with a keyboard-reachable "upload from computer" link. The file input is
 * visually hidden, not removed, so Tab reaches it and Enter or Space opens the dialog.
 */
export function FileDropzone({
  description,
  file,
  onFileSelect,
  onRemove,
  accept,
  error,
  warning,
  size = 'default',
  browseLabel = 'Upload from computer',
  removeLabel = 'Remove file',
  id,
  className,
}: FileDropzoneProps): ReactElement {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const errorId = `${inputId}-error`;
  const warningId = `${inputId}-warning`;
  const inputRef = useRef<HTMLInputElement | null>(null);
  const [dragging, setDragging] = useState(false);
  const [keyboardFocus, setKeyboardFocus] = useState(false);

  const stop = (event: DragEvent<HTMLElement>) => {
    event.preventDefault();
    event.stopPropagation();
  };

  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    stop(event);
    setDragging(false);
    const dropped = SELECT_FIRST(event.dataTransfer?.files);
    if (dropped) onFileSelect(dropped);
  };

  const handleDragOver = (event: DragEvent<HTMLDivElement>) => {
    stop(event);
    setDragging(true);
  };

  const handleDragLeave = (event: DragEvent<HTMLDivElement>) => {
    stop(event);
    setDragging(false);
  };

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    const picked = SELECT_FIRST(event.target.files);
    if (picked) onFileSelect(picked);
  };

  const handleRemove = () => {
    onRemove();
    if (inputRef.current) inputRef.current.value = '';
  };

  const describedBy =
    [file && error ? errorId : null, file && warning ? warningId : null]
      .filter(Boolean)
      .join(' ') || undefined;

  const classes = ['ss-dropzone'];
  if (className) classes.push(className);
  const areaClasses = ['ss-dropzone-area'];
  if (size === 'tall') areaClasses.push('ss-dropzone-area--tall');
  if (dragging) areaClasses.push('ss-dropzone-area--dragging');
  const rowClasses = ['ss-dropzone-file'];
  if (error) rowClasses.push('ss-dropzone-file--error');
  else if (warning) rowClasses.push('ss-dropzone-file--warning');

  return (
    <div className={classes.join(' ')}>
      <div
        className={areaClasses.join(' ')}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
      >
        <ColoredIcon icon={UploadGlyph} />
        <div className="ss-dropzone-description">{description}</div>
        <div className="ss-dropzone-browse">
          <span>Or</span>
          <label
            className={
              keyboardFocus ? 'ss-dropzone-link ss-dropzone-link--focus' : 'ss-dropzone-link'
            }
            htmlFor={inputId}
          >
            {browseLabel}
          </label>
          <input
            ref={inputRef}
            id={inputId}
            className="ss-dropzone-input"
            type="file"
            accept={accept}
            aria-describedby={describedBy}
            onChange={handleChange}
            onFocus={(event) => setKeyboardFocus(event.target.matches(':focus-visible'))}
            onBlur={() => setKeyboardFocus(false)}
          />
        </div>
      </div>
      {file && (
        <div className="ss-dropzone-result">
          <div className={rowClasses.join(' ')}>
            <div className="ss-dropzone-file-info">
              <svg
                className="ss-dropzone-file-icon"
                viewBox="0 0 22 26"
                aria-hidden="true"
                focusable="false"
              >
                <path
                  d="M19.805 20.5833H7.68971C7.10039 20.5833 6.60156 20.3791 6.19323 19.9708C5.7849 19.5624 5.58073 19.0636 5.58073 18.4743V2.85898C5.58073 2.26966 5.7849 1.77083 6.19323 1.3625C6.60156 0.954167 7.10039 0.75 7.68971 0.75H15.7891L21.914 6.87494V18.4743C21.914 19.0636 21.7098 19.5624 21.3015 19.9708C20.8932 20.3791 20.3943 20.5833 19.805 20.5833ZM14.9141 7.74994V2.49997H7.68971C7.59996 2.49997 7.51768 2.53736 7.44288 2.61215C7.36809 2.68695 7.3307 2.76923 7.3307 2.85898V18.4743C7.3307 18.5641 7.36809 18.6463 7.44288 18.7211C7.51768 18.7959 7.59996 18.8333 7.68971 18.8333H19.805C19.8948 18.8333 19.9771 18.7959 20.0519 18.7211C20.1266 18.6463 20.164 18.5641 20.164 18.4743V7.74994H14.9141ZM3.02305 25.2499C2.43372 25.2499 1.9349 25.0458 1.52656 24.6374C1.11823 24.2291 0.914062 23.7303 0.914062 23.141V7.75H2.66403V23.141C2.66403 23.2307 2.70142 23.313 2.77621 23.3878C2.85101 23.4626 2.93329 23.5 3.02305 23.5H14.914V25.2499L3.02305 25.2499Z"
                  fill="currentColor"
                />
              </svg>
              <span className="ss-dropzone-file-name">{file.name}</span>
            </div>
            <button
              type="button"
              className="ss-dropzone-remove"
              aria-label={removeLabel}
              onClick={handleRemove}
            >
              <svg viewBox="0 0 14 14" width="14" height="14" aria-hidden="true" focusable="false">
                <path
                  d="M1.4 14L0 12.6L5.6 7L0 1.4L1.4 0L7 5.6L12.6 0L14 1.4L8.4 7L14 12.6L12.6 14L7 8.4L1.4 14Z"
                  fill="currentColor"
                />
              </svg>
            </button>
          </div>
          {error && (
            <div
              id={errorId}
              className="ss-dropzone-message ss-dropzone-message--error"
              role="alert"
            >
              {error}
            </div>
          )}
          {warning && (
            <div
              id={warningId}
              className="ss-dropzone-message ss-dropzone-message--warning"
              role="status"
            >
              {warning}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
