import { useId } from 'react';
import type { ReactElement, ReactNode } from 'react';

import { DEFAULT_LEVEL_NAMES, DEFAULT_LEVEL_THRESHOLDS, getLevel } from './levels.js';
import type { Level, LevelThresholds } from './levels.js';

export interface LevelIndicatorProps {
  /** 0 to 100. Values outside are clamped. */
  value: number;
  thresholds?: LevelThresholds;
  /** Lower is better. */
  inverted?: boolean;
  /**
   * Fixed colour. Use it for a plain progress bar that is not a score: the level name
   * is then not announced.
   */
  level?: Level;
  /** Text before the bar; also the accessible name. */
  label?: string;
  /** Content after the bar, for example the number. */
  valueLabel?: ReactNode;
  /** Show the level name (Strong / Medium / Weak) as text, so colour is not the only cue. */
  showLevelName?: boolean;
  levelNames?: Record<Level, string>;
  className?: string;
}

export function LevelIndicator({
  value,
  thresholds = DEFAULT_LEVEL_THRESHOLDS,
  inverted = false,
  level: fixedLevel,
  label,
  valueLabel,
  showLevelName = false,
  levelNames = DEFAULT_LEVEL_NAMES,
  className,
}: LevelIndicatorProps): ReactElement {
  const labelId = useId();
  const safe = Number.isFinite(value) ? Math.min(100, Math.max(0, value)) : 0;
  const level = fixedLevel ?? getLevel(safe, thresholds, inverted);
  const classes = ['ss-level'];
  if (className) classes.push(className);

  return (
    <div className={classes.join(' ')}>
      {label && (
        <span id={labelId} className="ss-level-label">
          {label}
        </span>
      )}
      <div
        role="progressbar"
        className="ss-level-track"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={safe}
        aria-valuetext={fixedLevel ? `${safe}%` : `${safe}%, ${levelNames[level]}`}
        aria-labelledby={label ? labelId : undefined}
        aria-label={label ? undefined : 'Score'}
      >
        <div className={`ss-level-fill ss-level-fill-${level}`} style={{ width: `${safe}%` }} />
      </div>
      {valueLabel}
      {showLevelName && (
        <span className={`ss-level-name ss-level-name-${level}`}>{levelNames[level]}</span>
      )}
    </div>
  );
}
