export type Level = 'strong' | 'medium' | 'weak';

/** Upper bounds of Weak and Medium: below the first is Weak, below the second Medium. */
export type LevelThresholds = readonly [number, number];

/**
 * Decided by the owner on 10.10.2026: Strong 70-100, Medium 40-69, Weak 0-39. The backend
 * filters use the same cut-offs. Pages can also pass `thresholds` per indicator.
 */
export const DEFAULT_LEVEL_THRESHOLDS: LevelThresholds = [40, 70];

export const DEFAULT_LEVEL_NAMES: Record<Level, string> = {
  strong: 'Strong',
  medium: 'Medium',
  weak: 'Weak',
};

/**
 * `inverted` is for scores where lower is better (fraud): a low value is Strong.
 */
export function getLevel(
  value: number,
  thresholds: LevelThresholds = DEFAULT_LEVEL_THRESHOLDS,
  inverted = false
): Level {
  let level: Level = 'strong';
  if (value < thresholds[0]) level = 'weak';
  else if (value < thresholds[1]) level = 'medium';
  if (!inverted) return level;
  if (level === 'weak') return 'strong';
  return level === 'strong' ? 'weak' : 'medium';
}
