import { useEffect, useRef, useState, type ReactElement } from 'react';

export type ChatRole = 'user' | 'assistant';

export interface ChatMessage {
  id: string;
  role: ChatRole;
  /** Plain text. Rendered as text, never as HTML or Markdown. */
  text: string;
  timestamp?: Date | string | number;
}

function formatTime(value: Date | string | number, locale?: string): string {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleTimeString(locale, { hour: '2-digit', minute: '2-digit' });
}

export interface ChatBubbleProps {
  role: ChatRole;
  text: string;
  timestamp?: Date | string | number;
  /** Spoken before the text, e.g. "You" / "MarSel". Hidden visually. */
  author?: string;
  locale?: string;
  className?: string;
}

export function ChatBubble({
  role,
  text,
  timestamp,
  author,
  locale,
  className,
}: ChatBubbleProps): ReactElement {
  const classes = ['ss-chat-bubble', `ss-chat-bubble--${role}`];
  if (className) classes.push(className);
  const date = timestamp === undefined ? null : new Date(timestamp);
  const valid = date !== null && !Number.isNaN(date.getTime());
  return (
    <div className={classes.join(' ')}>
      {author ? <span className="ss-chat-sr">{author}: </span> : null}
      <p className="ss-chat-text">{text}</p>
      {valid && timestamp !== undefined ? (
        <time className="ss-chat-time" dateTime={date.toISOString()}>
          {formatTime(timestamp, locale)}
        </time>
      ) : null}
    </div>
  );
}

export interface TypingIndicatorProps {
  /** Accessible text, announced politely. */
  label?: string;
  className?: string;
}

/** Dots cycle with a timer rather than CSS keyframes, and stay still for reduced-motion users. */
export function TypingIndicator({
  label = 'Assistant is typing',
  className,
}: TypingIndicatorProps): ReactElement {
  const [step, setStep] = useState(0);
  useEffect(() => {
    const reduce =
      typeof window.matchMedia === 'function' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduce) return;
    const timer = setInterval(() => setStep((s) => (s + 1) % 3), 400);
    return () => clearInterval(timer);
  }, []);

  const classes = ['ss-chat-bubble', 'ss-chat-bubble--assistant', 'ss-chat-typing'];
  if (className) classes.push(className);
  return (
    <div role="status" aria-label={label} className={classes.join(' ')}>
      {[0, 1, 2].map((i) => (
        <span
          key={i}
          aria-hidden="true"
          className={i === step ? 'ss-chat-dot ss-chat-dot--active' : 'ss-chat-dot'}
        />
      ))}
    </div>
  );
}

export interface ChatThreadProps {
  messages: ChatMessage[];
  /** Shows the typing indicator after the last message. */
  typing?: boolean;
  /** Accessible name of the conversation. */
  label?: string;
  userLabel?: string;
  assistantLabel?: string;
  typingLabel?: string;
  locale?: string;
  className?: string;
}

export function ChatThread({
  messages,
  typing = false,
  label = 'Conversation',
  userLabel = 'You',
  assistantLabel = 'MarSel',
  typingLabel = `${assistantLabel} is typing`,
  locale,
  className,
}: ChatThreadProps): ReactElement {
  const ref = useRef<HTMLDivElement>(null);
  const stuck = useRef(true);

  // Follow new messages unless the reader scrolled up to read earlier ones.
  useEffect(() => {
    const el = ref.current;
    if (el && stuck.current) el.scrollTop = el.scrollHeight;
  }, [messages, typing]);

  const classes = ['ss-chat-thread'];
  if (className) classes.push(className);
  return (
    <div
      ref={ref}
      role="log"
      aria-label={label}
      aria-live="polite"
      aria-relevant="additions"
      // Scrollable regions must be reachable by keyboard.
      tabIndex={0}
      className={classes.join(' ')}
      onScroll={(event) => {
        const el = event.currentTarget;
        stuck.current = el.scrollHeight - el.scrollTop - el.clientHeight < 24;
      }}
    >
      {messages.map((m) => (
        <ChatBubble
          key={m.id}
          role={m.role}
          text={m.text}
          timestamp={m.timestamp}
          author={m.role === 'user' ? userLabel : assistantLabel}
          locale={locale}
        />
      ))}
      {typing ? <TypingIndicator label={typingLabel} /> : null}
    </div>
  );
}
