import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from 'react';
import { createPortal } from 'react-dom';

import { resolveContainer, type PortalContainer } from '../../internal/portal.js';

import { ToastContext, type ToastItem, type ToastOptions } from './toast-context.js';

interface ToastViewProps {
  toast: ToastItem;
  duration: number;
  dismissLabel: string;
  onDismiss: (id: string) => void;
}

function ToastView({ toast, duration, dismissLabel, onDismiss }: ToastViewProps) {
  const [paused, setPaused] = useState(false);
  const remaining = useRef(duration);
  const hovered = useRef(false);
  const focused = useRef(false);

  useEffect(() => {
    if (duration <= 0 || paused) return;
    const startedAt = Date.now();
    const timer = setTimeout(() => onDismiss(toast.id), remaining.current);
    return () => {
      clearTimeout(timer);
      remaining.current = Math.max(0, remaining.current - (Date.now() - startedAt));
    };
  }, [paused, duration, toast.id, onDismiss]);

  const sync = () => setPaused(hovered.current || focused.current);
  const classes = ['ss-toast', `ss-toast--${toast.tone ?? 'info'}`].join(' ');

  return (
    <div
      className={classes}
      onMouseEnter={() => {
        hovered.current = true;
        sync();
      }}
      onMouseLeave={() => {
        hovered.current = false;
        sync();
      }}
      onFocus={() => {
        focused.current = true;
        sync();
      }}
      onBlur={() => {
        focused.current = false;
        sync();
      }}
    >
      <div className="ss-toast-content">
        {toast.title ? <p className="ss-toast-title">{toast.title}</p> : null}
        <p className="ss-toast-message">{toast.message}</p>
      </div>
      <button
        type="button"
        className="ss-toast-close"
        aria-label={dismissLabel}
        onClick={() => onDismiss(toast.id)}
      >
        <span aria-hidden="true">×</span>
      </button>
    </div>
  );
}

export interface ToastProviderProps {
  /** Where the toast stack mounts. Default `document.body`. */
  container?: PortalContainer;
  /** Default auto-dismiss time in ms. */
  defaultDuration?: number;
  /** Oldest toasts are dropped beyond this. */
  max?: number;
  /** Label for the close button. */
  dismissLabel?: string;
  children?: ReactNode;
}

let counter = 0;

export function ToastProvider({
  container,
  defaultDuration = 5000,
  max = 5,
  dismissLabel = 'Dismiss notification',
  children,
}: ToastProviderProps): ReactElement {
  const [toasts, setToasts] = useState<ToastItem[]>([]);
  const [mountNode, setMountNode] = useState<HTMLElement | null>(null);

  useEffect(() => {
    setMountNode(resolveContainer(container));
  }, [container]);

  const dismiss = useCallback((id: string) => {
    setToasts((current) => current.filter((t) => t.id !== id));
  }, []);
  const dismissAll = useCallback(() => setToasts([]), []);
  const show = useCallback(
    (options: ToastOptions) => {
      counter += 1;
      const id = `ss-toast-${counter}`;
      setToasts((current) => [...current, { ...options, id }].slice(-max));
      return id;
    },
    [max]
  );

  const api = useMemo(() => ({ show, dismiss, dismissAll }), [show, dismiss, dismissAll]);

  const polite = toasts.filter(
    (t) => (t.politeness ?? (t.tone === 'error' ? 'assertive' : 'polite')) === 'polite'
  );
  const assertive = toasts.filter((t) => !polite.includes(t));

  const renderToast = (t: ToastItem) => (
    <ToastView
      key={t.id}
      toast={t}
      duration={t.duration ?? defaultDuration}
      dismissLabel={dismissLabel}
      onDismiss={dismiss}
    />
  );

  return (
    <ToastContext.Provider value={api}>
      {children}
      {mountNode
        ? createPortal(
            // Both live regions stay mounted, so announcements are not missed
            // when the first toast of a kind appears.
            <div className="ss-toast-viewport">
              <div role="status" aria-live="polite" aria-atomic="false" className="ss-toast-region">
                {polite.map(renderToast)}
              </div>
              <div
                role="alert"
                aria-live="assertive"
                aria-atomic="false"
                className="ss-toast-region"
              >
                {assertive.map(renderToast)}
              </div>
            </div>,
            mountNode
          )
        : null}
    </ToastContext.Provider>
  );
}
