import { Children, useId } from 'react';
import type { ElementType, ReactElement, ReactNode } from 'react';

export interface CardProps {
  title?: ReactNode;
  /** Level of the title heading. Pick the one that fits the page outline. */
  headingLevel?: 2 | 3 | 4 | 5;
  /**
   * BRD 7.2: a box with no data does not render. `false` hides the box
   * (for example `when={items.length > 0}`).
   */
  when?: boolean;
  /**
   * Also hide the box when `children` hold nothing to show (null, false, '' or an
   * empty list). Pass `false` for a box that must stay visible.
   */
  hideWhenEmpty?: boolean;
  children?: ReactNode;
  className?: string;
}

function hasContent(children: ReactNode): boolean {
  return Children.toArray(children).some((child) => child !== '');
}

export function Card({
  title,
  headingLevel = 2,
  when = true,
  hideWhenEmpty = true,
  children,
  className,
}: CardProps): ReactElement | null {
  const titleId = useId();

  if (!when) return null;
  if (hideWhenEmpty && !hasContent(children)) return null;

  const Heading = `h${headingLevel}` as ElementType;
  const classes = ['ss-card'];
  if (className) classes.push(className);

  return (
    <section className={classes.join(' ')} aria-labelledby={title ? titleId : undefined}>
      {title && (
        <Heading id={titleId} className="ss-card-title">
          {title}
        </Heading>
      )}
      {children}
    </section>
  );
}
