import { createContext, useContext, useEffect, useRef, type RefObject } from 'react';

/**
 * Overlays (Modal, Popover, Menu) portal to a container outside the tree that opened
 * them, so the DOM cannot say which one is on top or who belongs to whom. React context
 * can: an overlay rendered inside another one's children registers as its child layer.
 * Only the topmost layer traps focus or closes on Escape; focus and presses inside a
 * descendant layer count as inside the ancestor.
 */
export interface Layer {
  parent: Layer | null;
  getElement: () => HTMLElement | null;
}

const stack: Layer[] = [];

export const LayerContext = createContext<Layer | null>(null);

const isDescendant = (layer: Layer, ancestor: Layer): boolean => {
  for (let p = layer.parent; p; p = p.parent) if (p === ancestor) return true;
  return false;
};

export interface LayerHandle {
  layer: Layer;
  /** No other open layer sits above this one. */
  isTop: () => boolean;
  /** The node is inside this layer or inside a layer opened from it. */
  owns: (node: Node) => boolean;
}

/** Call before any effect that moves focus, so the layer is registered when focus lands. */
export function useLayer(active: boolean, elementRef: RefObject<HTMLElement>): LayerHandle {
  const parent = useContext(LayerContext);
  const ref = useRef<LayerHandle>();
  if (!ref.current) {
    const layer: Layer = { parent, getElement: () => elementRef.current };
    ref.current = {
      layer,
      isTop: () => {
        if (!stack.includes(layer)) return false;
        const leaves = stack.filter((l) => !stack.some((o) => isDescendant(o, l)));
        return leaves[leaves.length - 1] === layer;
      },
      owns: (node) =>
        stack.some(
          (l) => (l === layer || isDescendant(l, layer)) && !!l.getElement()?.contains(node)
        ),
    };
  }
  ref.current.layer.parent = parent;
  const { layer } = ref.current;

  useEffect(() => {
    if (!active) return;
    stack.push(layer);
    return () => {
      stack.splice(stack.indexOf(layer), 1);
    };
  }, [active, layer]);

  return ref.current;
}
