import type { HTMLAttributes, MouseEvent, ReactNode } from 'react';

export type BadgeVariant =
  | 'neutral'
  | 'success'
  | 'warning'
  | 'error'
  | 'strong'
  | 'medium'
  | 'weak';

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  /** `strong`, `medium` and `weak` are the signal levels from BRD 7.1. */
  variant?: BadgeVariant;
  /** Defaults to "Strong", "Medium" or "Weak" for the level variants. */
  children?: ReactNode;
  /** Adds a remove button. Clicking it does not reach the badge's own `onClick`. */
  onRemove?: () => void;
  /** Accessible name of the remove button, e.g. "Remove Country: Germany". */
  removeLabel?: string;
}

const LEVEL_TEXT: Partial<Record<BadgeVariant, string>> = {
  strong: 'Strong',
  medium: 'Medium',
  weak: 'Weak',
};

/** Colour is never the only signal: level badges carry their word, the dot is decoration. */
export function Badge({
  variant = 'neutral',
  className,
  children,
  onRemove,
  removeLabel = 'Remove',
  ...rest
}: BadgeProps) {
  const classes = ['ss-badge', `ss-badge--${variant}`];
  if (className) classes.push(className);

  const handleRemove = (event: MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();
    onRemove?.();
  };

  return (
    <span className={classes.join(' ')} {...rest}>
      {variant !== 'neutral' && (
        <span className={`ss-badge-dot ss-badge-dot--${variant}`} aria-hidden="true" />
      )}
      <span className="ss-badge-text">{children ?? LEVEL_TEXT[variant]}</span>
      {onRemove && (
        <button
          type="button"
          className="ss-badge-remove"
          aria-label={removeLabel}
          onClick={handleRemove}
        >
          <svg viewBox="0 0 16 16" width="12" height="12" aria-hidden="true" focusable="false">
            <path
              d="M3.5 3.5l9 9m0-9l-9 9"
              stroke="currentColor"
              strokeWidth="1.8"
              strokeLinecap="round"
            />
          </svg>
        </button>
      )}
    </span>
  );
}
