import { useId, useRef, useState } from 'react';
import type { KeyboardEvent, ReactNode } from 'react';

export type SelectSize = 'sm' | 'md';
export type SelectOption = string | { value: string; label?: ReactNode; disabled?: boolean };

export interface SelectProps {
  label?: ReactNode;
  /** A string selects one option. An array turns on multiple mode: `onChange` gets the clicked option, the page toggles it, and the list stays open. */
  value?: string | string[] | null;
  options?: SelectOption[] | null;
  onChange: (value: string) => void;
  /** Shown in the open list when there are no options (e.g. while they load). */
  emptyText?: string;
  /** Shown while `value` matches no option. */
  placeholder?: string;
  hint?: ReactNode;
  error?: ReactNode;
  required?: boolean;
  disabled?: boolean;
  /** `sm` is 40px high, `md` (default) 48px. */
  size?: SelectSize;
  /** Label for an option given as a plain string (or as `{ value }` without a label). */
  getOptionLabel?: (value: string) => ReactNode;
  /** Replaces the text inside the closed control, e.g. to add an icon. */
  renderValue?: (value: string | string[]) => ReactNode;
  /** Adds a hidden input so the value submits with a form. */
  name?: string;
  id?: string;
  'aria-label'?: string;
  /** Goes on the wrapper, so a page can set the width. */
  className?: string;
}

interface NormalizedOption {
  value: string;
  label: ReactNode;
  disabled: boolean;
}

/**
 * Accessible single select: a combobox (select-only pattern) with a listbox popup.
 * Keys: ArrowDown/ArrowUp open and move, Home/End jump, Enter or Space picks,
 * Escape closes, typing a letter jumps to the next option that starts with it.
 */
export function Select({
  label,
  value: valueProp,
  options: optionsProp,
  onChange,
  placeholder,
  emptyText = 'No options',
  hint,
  error,
  required,
  disabled,
  size = 'md',
  getOptionLabel,
  renderValue,
  name,
  id,
  'aria-label': ariaLabel,
  className,
}: SelectProps) {
  const generatedId = useId();
  const baseId = id ?? generatedId;
  const labelId = `${baseId}-label`;
  const listId = `${baseId}-list`;
  const hintId = `${baseId}-hint`;
  const errorId = `${baseId}-error`;
  const optionId = (index: number) => `${baseId}-option-${index}`;

  const items: NormalizedOption[] = (optionsProp ?? []).map((option) => {
    const optionValue = typeof option === 'string' ? option : option.value;
    const given = typeof option === 'string' ? undefined : option.label;
    return {
      value: optionValue,
      label: given ?? (getOptionLabel ? getOptionLabel(optionValue) : optionValue),
      disabled: typeof option === 'string' ? false : Boolean(option.disabled),
    };
  });

  const multiple = Array.isArray(valueProp);
  const value = valueProp ?? '';
  const isSelected = (item: NormalizedOption) =>
    Array.isArray(value) ? value.includes(item.value) : item.value === value;
  const selectedIndex = items.findIndex(isSelected);
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const typed = useRef({ text: '', timer: 0 });

  const enabledIndexes = items.flatMap((item, index) => (item.disabled ? [] : [index]));
  const hasError = Boolean(error);

  const openList = (preferred: number) => {
    if (disabled) return;
    setActiveIndex(preferred);
    setOpen(true);
  };

  const closeList = () => setOpen(false);

  const choose = (index: number) => {
    const item = items[index];
    if (!item || item.disabled) return;
    onChange(item.value);
    if (!multiple) setOpen(false);
  };

  const move = (step: 1 | -1) => {
    if (enabledIndexes.length === 0) return;
    const position = enabledIndexes.indexOf(activeIndex);
    if (position === -1) {
      setActiveIndex(step === 1 ? enabledIndexes[0] : enabledIndexes[enabledIndexes.length - 1]);
      return;
    }
    const next = Math.min(Math.max(position + step, 0), enabledIndexes.length - 1);
    setActiveIndex(enabledIndexes[next]);
  };

  const firstEnabledFromSelected = () =>
    selectedIndex !== -1 && !items[selectedIndex].disabled
      ? selectedIndex
      : enabledIndexes[0] ?? -1;

  const jumpToText = (char: string) => {
    const state = typed.current;
    window.clearTimeout(state.timer);
    state.text += char.toLowerCase();
    state.timer = window.setTimeout(() => {
      state.text = '';
    }, 500);
    const startsWith = (index: number) =>
      typeof items[index].label === 'string' || typeof items[index].label === 'number'
        ? String(items[index].label).toLowerCase().startsWith(state.text)
        : items[index].value.toLowerCase().startsWith(state.text);
    const from = enabledIndexes.indexOf(activeIndex);
    const ordered = [...enabledIndexes.slice(from + 1), ...enabledIndexes.slice(0, from + 1)];
    const match = ordered.find(startsWith);
    if (match === undefined) return;
    if (!open) setOpen(true);
    setActiveIndex(match);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (disabled || event.altKey || event.ctrlKey || event.metaKey) return;

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        if (open) move(1);
        else openList(firstEnabledFromSelected());
        break;
      case 'ArrowUp':
        event.preventDefault();
        if (open) move(-1);
        else openList(firstEnabledFromSelected());
        break;
      case 'Home':
        event.preventDefault();
        if (!open) setOpen(true);
        setActiveIndex(enabledIndexes[0] ?? -1);
        break;
      case 'End':
        event.preventDefault();
        if (!open) setOpen(true);
        setActiveIndex(enabledIndexes[enabledIndexes.length - 1] ?? -1);
        break;
      case 'Enter':
      case ' ':
        event.preventDefault();
        if (open) choose(activeIndex);
        else openList(firstEnabledFromSelected());
        break;
      case 'Escape':
        if (open) {
          event.preventDefault();
          closeList();
        }
        break;
      default:
        if (event.key.length === 1) jumpToText(event.key);
    }
  };

  const selectedItems = items.filter(isSelected);
  let display: ReactNode;
  if (renderValue && value.length > 0) display = renderValue(value);
  else if (selectedItems.length > 0)
    display = selectedItems.map((item, index) => (
      <span key={item.value}>
        {index > 0 && ', '}
        {item.label}
      </span>
    ));
  else display = <span className="ss-select-placeholder">{placeholder}</span>;

  const describedIds = [hint ? hintId : undefined, hasError ? errorId : undefined]
    .filter(Boolean)
    .join(' ');

  const triggerClasses = ['ss-select-trigger'];
  if (size === 'sm') triggerClasses.push('ss-select-trigger--sm');
  if (hasError) triggerClasses.push('ss-select-trigger--error');
  if (disabled) triggerClasses.push('ss-select-trigger--disabled');

  return (
    <div className={className ? `ss-field ${className}` : 'ss-field'}>
      {label && (
        <span className="ss-field-label" id={labelId}>
          {label}
          {required && (
            <span className="ss-field-required" aria-hidden="true">
              {' *'}
            </span>
          )}
        </span>
      )}
      <div className="ss-select-control">
        <div
          id={baseId}
          role="combobox"
          className={triggerClasses.join(' ')}
          tabIndex={disabled ? -1 : 0}
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-controls={listId}
          aria-activedescendant={open && activeIndex >= 0 ? optionId(activeIndex) : undefined}
          aria-labelledby={label ? labelId : undefined}
          aria-label={label ? undefined : ariaLabel}
          aria-required={required || undefined}
          aria-disabled={disabled || undefined}
          aria-invalid={hasError || undefined}
          aria-describedby={describedIds || undefined}
          onClick={() => (open ? closeList() : openList(firstEnabledFromSelected()))}
          onBlur={closeList}
          onKeyDown={onKeyDown}
        >
          <span className="ss-select-value">{display}</span>
          <svg
            className={open ? 'ss-select-arrow ss-select-arrow--open' : 'ss-select-arrow'}
            viewBox="0 0 12 8"
            aria-hidden="true"
            focusable="false"
          >
            <path d="M1 1.5 6 6.5 11 1.5" fill="none" stroke="currentColor" strokeWidth="1.8" />
          </svg>
        </div>
        <ul
          id={listId}
          role="listbox"
          aria-labelledby={label ? labelId : undefined}
          aria-label={label ? undefined : ariaLabel}
          aria-multiselectable={multiple || undefined}
          className={open ? 'ss-select-list ss-select-list--open' : 'ss-select-list'}
          hidden={!open}
        >
          {items.length === 0 && (
            <li role="presentation" className="ss-select-empty">
              {emptyText}
            </li>
          )}
          {items.map((item, index) => {
            const classes = ['ss-select-option'];
            if (isSelected(item)) classes.push('ss-select-option--selected');
            if (index === activeIndex) classes.push('ss-select-option--active');
            if (item.disabled) classes.push('ss-select-option--disabled');
            return (
              <li
                key={item.value}
                id={optionId(index)}
                role="option"
                className={classes.join(' ')}
                aria-selected={isSelected(item)}
                aria-disabled={item.disabled || undefined}
                // Keeps focus on the combobox, so choosing does not blur and close it first.
                onMouseDown={(event) => event.preventDefault()}
                onMouseMove={() => !item.disabled && setActiveIndex(index)}
                onClick={() => choose(index)}
              >
                {item.label}
              </li>
            );
          })}
        </ul>
      </div>
      {name &&
        (Array.isArray(value) ? value : [value]).map((entry) => (
          <input key={entry} type="hidden" name={name} value={entry} />
        ))}
      {hint && (
        <span id={hintId} className="ss-field-hint">
          {hint}
        </span>
      )}
      {hasError && (
        <span id={errorId} className="ss-field-error" role="alert">
          {error}
        </span>
      )}
    </div>
  );
}
