import { forwardRef, useId } from 'react';
import type { InputHTMLAttributes, ReactNode } from 'react';

export interface SwitchProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'size' | 'role'> {
  /** Text before the switch. Without it, give the input an `aria-label`. */
  label?: ReactNode;
  hint?: ReactNode;
  /** Goes on the wrapper, so a page can set spacing or width. */
  className?: string;
}

/** A native checkbox with `role="switch"`: Space toggles, screen readers say on/off. */
export const Switch = forwardRef<HTMLInputElement, SwitchProps>(function Switch(
  { label, hint, className, id, disabled, 'aria-describedby': describedBy, ...rest },
  ref
) {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const hintId = `${inputId}-hint`;
  const describedIds = [describedBy, hint ? hintId : undefined].filter(Boolean).join(' ');
  const rowClasses = disabled ? 'ss-switch-row ss-switch-row--disabled' : 'ss-switch-row';

  return (
    <div className={className ? `ss-field ${className}` : 'ss-field'}>
      <label className={rowClasses} htmlFor={inputId}>
        {label && <span className="ss-switch-text">{label}</span>}
        <input
          ref={ref}
          id={inputId}
          type="checkbox"
          role="switch"
          className="ss-switch"
          disabled={disabled}
          aria-describedby={describedIds || undefined}
          {...rest}
        />
      </label>
      {hint && (
        <span id={hintId} className="ss-field-hint">
          {hint}
        </span>
      )}
    </div>
  );
});
