import { useId } from 'react';
import type { ElementType, ReactElement, ReactNode } from 'react';

import { cx } from '../../classes.js';
import { Button } from '../Button/index.js';

export interface LockedSectionProps {
  /** What the section does, in a few words. */
  title: ReactNode;
  /** What the customer gets by unlocking it. */
  description?: ReactNode;
  /** Plan that includes the section, for example "Pro". */
  requiredPlan?: string;
  upgradeLabel?: string;
  /** Upgrade as a link. Use `onUpgrade` for an in-page action. One of the two is needed. */
  upgradeHref?: string;
  onUpgrade?: () => void;
  /**
   * Blurred sample of the locked content. It is hidden from screen readers and from the
   * keyboard, and nothing in it can be used.
   */
  preview?: ReactNode;
  headingLevel?: 2 | 3 | 4 | 5;
  className?: string;
}

/** Content is not focusable or announced while the section is locked. */
function makeInert(node: HTMLElement | null): void {
  if (node) node.setAttribute('inert', '');
}

export function LockedSection({
  title,
  description,
  requiredPlan,
  upgradeLabel = 'Upgrade plan',
  upgradeHref,
  onUpgrade,
  preview,
  headingLevel = 3,
  className,
}: LockedSectionProps): ReactElement {
  const titleId = useId();
  const Heading = `h${headingLevel}` as ElementType;
  const classes = ['ss-locked'];
  if (preview) classes.push('ss-locked-with-preview');
  if (className) classes.push(className);

  const panel = (
    <div className={cx('ss-locked-panel', !!preview && 'ss-locked-panel-raised')}>
      <svg
        aria-hidden="true"
        focusable="false"
        className="ss-locked-icon"
        viewBox="0 0 24 24"
        fill="currentColor"
      >
        <path d="M12 1a5 5 0 0 0-5 5v3H6a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V11a2 2 0 0 0-2-2h-1V6a5 5 0 0 0-5-5Zm-3 8V6a3 3 0 1 1 6 0v3H9Z" />
      </svg>
      <Heading id={titleId} className="ss-locked-title">
        {title}
      </Heading>
      {requiredPlan && <p className="ss-locked-plan">Available on the {requiredPlan} plan</p>}
      {description && <p className="ss-locked-description">{description}</p>}
      <div className="ss-locked-action">
        {upgradeHref ? (
          <a className="ss-button ss-button--contained-primary ss-locked-button" href={upgradeHref}>
            {upgradeLabel}
          </a>
        ) : (
          <Button variant="contained-primary" className="ss-locked-button" onClick={onUpgrade}>
            {upgradeLabel}
          </Button>
        )}
      </div>
    </div>
  );

  return (
    <section className={classes.join(' ')} aria-labelledby={titleId}>
      {preview ? (
        <>
          <div className="ss-locked-preview" aria-hidden="true" ref={makeInert}>
            {preview}
          </div>
          <div className="ss-locked-scrim">{panel}</div>
        </>
      ) : (
        panel
      )}
    </section>
  );
}
