import type { ReactNode } from 'react';

import { Tooltip } from '../Tooltip/index.js';

type InfoField = 'source' | 'confidence' | 'reason' | 'date';

export interface InfoIconProps {
  /** Where the number or statement comes from. */
  source?: ReactNode;
  /** How sure we are, e.g. "High" or "82%". */
  confidence?: ReactNode;
  /** Why the value is what it is. */
  reason?: ReactNode;
  /** When it was measured. A `Date` is shown as YYYY-MM-DD. */
  date?: string | Date;
  /** Accessible name of the icon button. */
  label?: string;
  /** Row titles, to translate or reword. */
  labels?: Partial<Record<InfoField, string>>;
  className?: string;
}

const DEFAULT_LABELS: Record<InfoField, string> = {
  source: 'Source',
  confidence: 'Confidence',
  reason: 'Reason',
  date: 'Date',
};

/** The "i" icon from BRD 7.1: source, confidence, reason and date of a value, in a tooltip. */
export function InfoIcon({
  source,
  confidence,
  reason,
  date,
  label = 'More information',
  labels,
  className,
}: InfoIconProps) {
  const titles = { ...DEFAULT_LABELS, ...labels };
  const dateText = date instanceof Date ? date.toISOString().slice(0, 10) : date;
  const rows: [InfoField, ReactNode][] = [
    ['source', source],
    ['confidence', confidence],
    ['reason', reason],
    ['date', dateText],
  ];

  return (
    <Tooltip
      className={className}
      content={
        <dl className="ss-info-list">
          {rows
            .filter(([, value]) => value !== undefined && value !== null && value !== '')
            .map(([field, value]) => (
              <div className="ss-info-row" key={field}>
                <dt className="ss-info-term">{titles[field]}</dt>
                <dd className="ss-info-desc">{value}</dd>
              </div>
            ))}
        </dl>
      }
    >
      <button type="button" className="ss-info-icon" aria-label={label}>
        <svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false">
          <circle cx="12" cy="12" r="10" fill="none" stroke="currentColor" strokeWidth="2" />
          <path d="M12 11v6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          <circle cx="12" cy="7.5" r="1.25" fill="currentColor" />
        </svg>
      </button>
    </Tooltip>
  );
}
