import { forwardRef, useId } from 'react';
import type { InputHTMLAttributes, ReactNode } from 'react';

export interface CheckboxProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'size'> {
  /** Text next to the box. Without it, give the input an `aria-label`. */
  label?: ReactNode;
  hint?: ReactNode;
  /** Error message. Sets `aria-invalid` and is announced. */
  error?: ReactNode;
  /** Goes on the wrapper, so a page can set spacing or width. */
  className?: string;
}

/** A native checkbox, so Space, Tab, form submit and screen readers work as they do everywhere. */
export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(function Checkbox(
  { label, hint, error, className, id, disabled, 'aria-describedby': describedBy, ...rest },
  ref
) {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const hintId = `${inputId}-hint`;
  const errorId = `${inputId}-error`;
  const hasError = Boolean(error);

  const describedIds = [describedBy, hint ? hintId : undefined, hasError ? errorId : undefined]
    .filter(Boolean)
    .join(' ');

  const inputClasses = hasError ? 'ss-checkbox ss-checkbox--error' : 'ss-checkbox';
  const rowClasses = disabled ? 'ss-check-row ss-check-row--disabled' : 'ss-check-row';

  return (
    <div className={className ? `ss-field ${className}` : 'ss-field'}>
      <label className={rowClasses} htmlFor={inputId}>
        <input
          ref={ref}
          id={inputId}
          type="checkbox"
          className={inputClasses}
          disabled={disabled}
          aria-invalid={hasError || undefined}
          aria-describedby={describedIds || undefined}
          {...rest}
        />
        {label && <span className="ss-check-text">{label}</span>}
      </label>
      {hint && (
        <span id={hintId} className="ss-field-hint">
          {hint}
        </span>
      )}
      {hasError && (
        <span id={errorId} className="ss-field-error" role="alert">
          {error}
        </span>
      )}
    </div>
  );
});
