import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useRef,
  useState,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactElement,
  type ReactNode,
  type Ref,
} from 'react';

import type { PortalContainer } from '../../internal/portal.js';
import { Popover, type PopoverPlacement } from '../Popover/Popover.js';

const MenuContext = createContext<{ close: () => void } | null>(null);

export interface MenuProps {
  /** Content of the button that opens the menu. */
  label: ReactNode;
  /** Name for the button when `label` is not text (an icon). */
  'aria-label'?: string;
  children: ReactNode;
  placement?: PopoverPlacement;
  offset?: number;
  matchButtonWidth?: boolean;
  container?: PortalContainer;
  /** Fires whenever the menu opens or closes. */
  onOpenChange?: (open: boolean) => void;
  className?: string;
  /** Class for the menu panel. */
  menuClassName?: string;
  /** Class for the positioned wrapper around the panel (e.g. a z-index). */
  popoverClassName?: string;
}

const enabledItems = (menu: HTMLElement) =>
  Array.from(menu.querySelectorAll<HTMLElement>('[role="menuitem"]:not([aria-disabled="true"])'));

export function Menu({
  label,
  'aria-label': ariaLabel,
  children,
  placement = 'bottom-start',
  offset,
  matchButtonWidth,
  container,
  onOpenChange,
  className,
  menuClassName,
  popoverClassName,
}: MenuProps): ReactElement {
  const buttonId = useId();
  const menuId = useId();
  const buttonRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const [open, setOpenState] = useState(false);
  const onOpenChangeRef = useRef(onOpenChange);
  onOpenChangeRef.current = onOpenChange;
  const setOpen = useCallback((next: boolean) => {
    setOpenState(next);
    onOpenChangeRef.current?.(next);
  }, []);
  const [start, setStart] = useState<'first' | 'last'>('first');
  const typed = useRef({ text: '', timer: 0 });

  const close = useCallback(() => setOpen(false), [setOpen]);
  const openAt = (where: 'first' | 'last') => {
    setStart(where);
    setOpen(true);
  };

  useEffect(() => {
    if (!open || !menuRef.current) return;
    const items = enabledItems(menuRef.current);
    (start === 'last' ? items[items.length - 1] : items[0])?.focus();
  }, [open, start]);

  useEffect(() => () => window.clearTimeout(typed.current.timer), []);

  const onButtonKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      openAt('first');
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      openAt('last');
    }
  };

  const onMenuKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const items = enabledItems(event.currentTarget);
    if (items.length === 0) return;
    const index = items.indexOf(document.activeElement as HTMLElement);
    let target: HTMLElement | undefined;

    if (event.key === 'ArrowDown') target = items[(index + 1) % items.length];
    else if (event.key === 'ArrowUp') target = items[(index - 1 + items.length) % items.length];
    else if (event.key === 'Home') target = items[0];
    else if (event.key === 'End') target = items[items.length - 1];
    else if (event.key === 'Tab') {
      // The panel is portalled away from the button, so natural Tab order is
      // meaningless: close and give focus back.
      event.preventDefault();
      close();
      return;
    } else if (event.key.length === 1 && !event.ctrlKey && !event.metaKey && !event.altKey) {
      if (event.key === ' ' && typed.current.text === '') return; // Space activates
      window.clearTimeout(typed.current.timer);
      typed.current.text += event.key.toLowerCase();
      typed.current.timer = window.setTimeout(() => (typed.current.text = ''), 500);
      const text = typed.current.text;
      const repeated = [...text].every((c) => c === text[0]);
      const from = repeated ? index + 1 : Math.max(index, 0);
      const query = repeated ? text[0] : text;
      for (let i = 0; i < items.length; i += 1) {
        const item = items[(from + i) % items.length];
        if ((item.textContent ?? '').trim().toLowerCase().startsWith(query)) {
          target = item;
          break;
        }
      }
      if (!target) return;
    } else return;

    event.preventDefault();
    target?.focus();
  };

  const buttonClasses = ['ss-menu-button'];
  if (className) buttonClasses.push(className);
  const panelClasses = ['ss-menu'];
  if (menuClassName) panelClasses.push(menuClassName);

  return (
    <>
      <button
        ref={buttonRef}
        id={buttonId}
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? menuId : undefined}
        aria-label={ariaLabel}
        className={buttonClasses.join(' ')}
        onClick={() => (open ? close() : openAt('first'))}
        onKeyDown={onButtonKeyDown}
      >
        {label}
      </button>
      <Popover
        open={open}
        onClose={close}
        anchorRef={buttonRef}
        placement={placement}
        offset={offset}
        matchAnchorWidth={matchButtonWidth}
        container={container}
        role="none"
        autoFocus={false}
        className={popoverClassName}
      >
        <MenuContext.Provider value={{ close }}>
          <div
            ref={menuRef}
            id={menuId}
            role="menu"
            aria-labelledby={ariaLabel ? undefined : buttonId}
            aria-label={ariaLabel}
            className={panelClasses.join(' ')}
            onKeyDown={onMenuKeyDown}
          >
            {children}
          </div>
        </MenuContext.Provider>
      </Popover>
    </>
  );
}

export interface MenuItemRenderProps extends HTMLAttributes<HTMLElement> {
  ref: Ref<never>;
  role: 'menuitem';
  tabIndex: number;
}

export interface MenuItemProps {
  onSelect?: () => void;
  disabled?: boolean;
  className?: string;
  children: ReactNode;
  /**
   * Render the item as something other than a button, e.g. a router link:
   * `render={(props) => <Link to="/x" {...props} />}`. Spread `props` on the element.
   */
  render?: (props: MenuItemRenderProps) => ReactElement;
}

export function MenuItem({
  onSelect,
  disabled,
  className,
  children,
  render,
}: MenuItemProps): ReactElement {
  const ctx = useContext(MenuContext);
  if (!ctx) throw new Error('MenuItem must be rendered inside <Menu>');
  const classes = ['ss-menu-item'];
  if (disabled) classes.push('ss-menu-item--disabled');
  if (className) classes.push(className);

  const props = {
    role: 'menuitem' as const,
    tabIndex: -1,
    'aria-disabled': disabled || undefined,
    className: classes.join(' '),
    children,
    onClick: () => {
      if (disabled) return;
      onSelect?.();
      ctx.close();
    },
  };
  if (render) {
    // A button activates on Space natively; a link does not.
    const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
      if (event.key === ' ') {
        event.preventDefault();
        event.currentTarget.click();
      }
    };
    return render({ ...props, onKeyDown } as unknown as MenuItemRenderProps);
  }
  return <button type="button" {...props} />;
}
