import type { ReactElement, ReactNode } from 'react';

export interface ContactBadgeProps {
  /** Usually a `ColoredIcon`. */
  icon: ReactNode;
  /** Bold first line, for example "Email". */
  label: ReactNode;
  /** Second line, for example the address. */
  text: ReactNode;
  className?: string;
}

/** An icon with a label and a value under it, centred; a way to reach somebody. */
export function ContactBadge({ icon, label, text, className }: ContactBadgeProps): ReactElement {
  const classes = ['ss-contact-badge'];
  if (className) classes.push(className);

  return (
    <div className={classes.join(' ')}>
      <div className="ss-contact-badge-icon">{icon}</div>
      <div className="ss-contact-badge-body">
        <span className="ss-contact-badge-label">{label}</span>
        <span className="ss-contact-badge-text">{text}</span>
      </div>
    </div>
  );
}
